-- A computer's signed request names only its device id, and the Worker must learn which client to
-- scope to before it can read the key that checks the signature. This answers only that: the client
-- of a computer that is still paired (never a removed one), and nothing else about it. SECURITY
-- DEFINER, as 0071's helper, so it reads past row-level security as the migrating owner;
-- `row_security = off` makes it fail rather than answer from a filtered view if that is ever not so.
-- The signature is then checked inside that one client (withTenant), against the key read there.
-- DECISION: a definer lookup, not each client in turn (as Meta's webhook finds a number): a
-- computer asks every 25 seconds, and the answer names no more than the id the caller already has.
CREATE FUNCTION desktop_device_tenant(p_device_id uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = pg_catalog, public
SET row_security = off
AS $$
  SELECT d.tenant_id FROM public.desktop_device d
  WHERE d.id = p_device_id AND d.revoked_at IS NULL
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION desktop_device_tenant(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION desktop_device_tenant(uuid) TO cs_runtime;
